// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Review reproducers for Frontier Statistics V2 join-estimate robustness. Each test builds a real mapped generation
 * over a synthetic snapshot with a known exact join size and checks the planner-facing estimate.
 */
class FrontierEstimationReviewReproTest {

	private static final long HUB = 5_000_000L;

	/**
	 * Candidate 2: the forward Omni bridge samples the large side, never sees the eight rows that reach the hub, and
	 * returns a zero point estimate. The reverse direction (sampling the hub side) would see the hub in almost every
	 * sampled row and has exact degrees on the other side, but it is only tried when the forward direction is
	 * unavailable.
	 */
	@Test
	void hiddenHubBridgeIsNotEstimatedAsEmpty(@TempDir Path directory) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 1; i <= 20_000; i++) {
			rows.add(new long[] { 1_000_000L + i, 7L, 2_000_000L + i, 0L });
		}
		for (int j = 1; j <= 8; j++) {
			rows.add(new long[] { 3_000_000L + j, 7L, HUB, 0L });
		}
		for (int m = 1; m <= 20_000; m++) {
			rows.add(new long[] { HUB, 8L, 6_000_000L + m, 0L });
			rows.add(new long[] { 7_000_000L + m, 8L, 8_000_000L + m, 0L });
		}
		Snapshot snapshot = new Snapshot(91L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 1024, 256, 256, 2L * 1024L * 1024L);
		try (LmdbStatisticsService service = build(directory, snapshot, config)) {
			FrontierJoinProbe forward = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			FrontierJoinProbe reverse = new FrontierJoinProbe(predicate(8L), 0, predicate(7L), 2);
			long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0);
			FrontierJoinEstimate forwardEstimate = service.estimateJoin(snapshot.snapshotEpoch(), forward);
			FrontierJoinEstimate reverseEstimate = service.estimateJoin(snapshot.snapshotEpoch(), reverse);
			System.out.println("[review-f6] hidden-hub exact=" + exact + " forward=" + forwardEstimate
					+ " reverse=" + reverseEstimate);
			assertTrue(forwardEstimate.pointRows() >= exact / 16.0d,
					"p7.o = p8.s forward estimate must stay within q-error 16 of exact=" + exact + " but was "
							+ forwardEstimate + " (reverse orientation gives " + reverseEstimate + ")");
		}
	}

	/**
	 * Candidate 1: sixteen predicate pairs, each with a disjoint heavy hitter on each side plus a modest shared key
	 * set. Exact join size is small relative to the second frequency moments, which is the regime where Fast-AGMS lanes
	 * are dominated by noise. The estimator must not report an interval that excludes the exact size while claiming
	 * confidence, and it must not collapse to a (near) zero point.
	 */
	@Test
	void disjointHeavyHittersKeepExactInsideReportedInterval(@TempDir Path directory) throws Exception {
		assertDisjointHeavyHitters(directory, 60, 4, FrontierLeafProbe.BOTH_PLANES);
	}

	/**
	 * Candidate 1 (rare shared keys): with only three shared join keys per pair the coordinated center sample usually
	 * retains no positive center, Omni bridges see sampled zero degrees, and the estimate falls through to Fast-AGMS
	 * whose clamped lanes are noise-dominated.
	 */
	@Test
	void rareSharedKeysKeepExactInsideReportedInterval(@TempDir Path directory) throws Exception {
		assertDisjointHeavyHitters(directory, 3, 40, FrontierLeafProbe.BOTH_PLANES);
	}

	/**
	 * Same data, explicit-plane probes: this is the only probe shape for which the Fast-AGMS fallback is reachable
	 * (its shape check requires the predicate in the heavy list of every probed plane, so BOTH_PLANES probes on a
	 * store without inferred copies never reach it).
	 */
	@Test
	void rareSharedKeysExplicitPlaneAgmsFallbackKeepsExactInsideInterval(@TempDir Path directory)
			throws Exception {
		assertDisjointHeavyHitters(directory, 1, 70, FrontierLeafProbe.EXPLICIT);
	}

	private static void assertDisjointHeavyHitters(Path directory, int sharedKeys, int sharedDegree, int planeMask)
			throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		int pairs = 16;
		int heavyRows = 3_000;
		long nextSubject = 10_000_000L;
		long nextObject = 50_000_000L;
		for (int pair = 0; pair < pairs; pair++) {
			long left = 100L + 2L * pair;
			long right = left + 1L;
			long heavyLeft = 90_000_000L + pair;
			long heavyRight = 91_000_000L + pair;
			for (int row = 0; row < heavyRows; row++) {
				rows.add(new long[] { nextSubject++, left, heavyLeft, 0L });
				rows.add(new long[] { heavyRight, right, nextObject++, 0L });
			}
			for (int key = 0; key < sharedKeys; key++) {
				long shared = 92_000_000L + pair * 1_000L + key;
				for (int degree = 0; degree < sharedDegree; degree++) {
					rows.add(new long[] { nextSubject++, left, shared, 0L });
					rows.add(new long[] { shared, right, nextObject++, 0L });
				}
			}
		}
		Snapshot snapshot = new Snapshot(92L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				64L * 1024L * 1024L, 64, 256, 256, 2L * 1024L * 1024L);
		try (LmdbStatisticsService service = build(directory, snapshot, config)) {
			int excluded = 0;
			int collapsed = 0;
			double worstQ = 1.0d;
			StringBuilder report = new StringBuilder();
			for (int pair = 0; pair < pairs; pair++) {
				long left = 100L + 2L * pair;
				long right = left + 1L;
				long exact = snapshot.exactPredicateJoin(left, 2, right, 0);
				FrontierJoinEstimate estimate = service.estimateJoin(snapshot.snapshotEpoch(),
						new FrontierJoinProbe(predicate(left, planeMask), 2, predicate(right, planeMask), 0));
				if (estimate.fallbackReason() != FrontierFallbackReason.NONE) {
					report.append("\n  pair=").append(pair).append(" exact=").append(exact)
							.append(" UNKNOWN (typed fallback, not a claim) ").append(estimate);
					continue;
				}
				double q = qError(estimate.pointRows(), exact);
				worstQ = Math.max(worstQ, q);
				boolean outside = exact < estimate.lowerRows() || exact > estimate.upperRows();
				if (outside) {
					excluded++;
				}
				if (estimate.pointRows() < exact / 100.0d) {
					collapsed++;
				}
				report.append("\n  pair=").append(pair).append(" exact=").append(exact).append(" q=")
						.append(String.format("%.1f", q)).append(outside ? " EXCLUDED " : " ").append(estimate);
			}
			System.out.println("[review-f6] disjoint-heavy-hitters plane=" + planeMask + " shared=" + sharedKeys + "x"
					+ sharedDegree
					+ " worstQ=" + worstQ + " excluded=" + excluded + " collapsed=" + collapsed + report);
			assertTrue(excluded == 0 && collapsed == 0 && worstQ <= 16.0d,
					"join estimates must keep exact inside [lower, upper] and within q-error 16; worstQ=" + worstQ
							+ ", excluded=" + excluded + ", collapsed(point<exact/100)=" + collapsed + report);
		}
	}

	/**
	 * Candidate 8: one planner join estimate has no work bound. A 4,000-key sampled side whose keys all have positive
	 * degree forces one full candidate-cell scan (up to the 8,192-row witness ceiling) per key, per lane.
	 */
	@Test
	void singleJoinEstimateHasBoundedPlanningWork(@TempDir Path directory) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 0; i < 50_000; i++) {
			rows.add(new long[] { 10_000_000L + i, 7L, 1_000_000L + (i % 4_000), 0L });
			rows.add(new long[] { 1_000_000L + (i % 4_000), 8L, 20_000_000L + i, 0L });
		}
		Snapshot snapshot = new Snapshot(93L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 2, 8_192, 256, 8L * 1024L * 1024L);
		try (LmdbStatisticsService service = build(directory, snapshot, config)) {
			FrontierJoinProbe probe = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			FrontierJoinEstimate warm = service.estimateJoin(snapshot.snapshotEpoch(), probe);
			long best = Long.MAX_VALUE;
			for (int run = 0; run < 3; run++) {
				long started = System.nanoTime();
				service.estimateJoin(snapshot.snapshotEpoch(), probe);
				best = Math.min(best, System.nanoTime() - started);
			}
			long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0);
			System.out.println("[review-f6] single estimateJoin best-of-3 millis=" + best / 1_000_000.0d
					+ " exact=" + exact + " estimate=" + warm);
			assertTrue(best < 50_000_000L, "one two-pattern join estimate took " + best / 1_000_000.0d
					+ " ms; the planner issues many of these per query");
		}
	}

	private static double qError(double estimate, double exact) {
		double e = Math.max(1.0d, estimate);
		double t = Math.max(1.0d, exact);
		return Math.max(e / t, t / e);
	}

	private static FrontierLeafProbe predicate(long predicate) {
		return predicate(predicate, FrontierLeafProbe.BOTH_PLANES);
	}

	private static FrontierLeafProbe predicate(long predicate, int planeMask) {
		return new FrontierLeafProbe(planeMask, FrontierLeafProbe.PREDICATE, 0L, predicate, 0L, 0L);
	}

	private static LmdbStatisticsService build(Path directory, Snapshot snapshot,
			FrontierStatisticsBuildConfig config) throws IOException {
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				256L * 1024L * 1024L, 32L * 1024L * 1024L, 64L * 1024L * 1024L, 32L * 1024L * 1024L);
		FrontierStatisticsManifest manifest = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		new FrontierStatisticsManifestStore(directory, NioFrontierFileOps.INSTANCE).publish(manifest);
		return LmdbStatisticsService.open(directory, governor, 1024L * 1024L * 1024L, 60_000L);
	}

	private static final class Snapshot implements FrontierSnapshotSource {

		private final long epoch;
		private final List<long[]> explicit;

		private Snapshot(long epoch, List<long[]> explicit) {
			this.epoch = epoch;
			this.explicit = List.copyOf(explicit);
		}

		@Override
		public long snapshotEpoch() {
			return epoch;
		}

		@Override
		public long rowCount(boolean explicitPlane) {
			return explicitPlane ? explicit.size() : 0L;
		}

		@Override
		public long scan(boolean explicitPlane, RawQuadSink sink) throws IOException {
			if (!explicitPlane) {
				return 0L;
			}
			for (long[] row : explicit) {
				sink.accept(row[0], row[1], row[2], row[3]);
			}
			return explicit.size();
		}

		@Override
		public boolean contains(long subjectId, long predicateId, long objectId, long contextId,
				boolean explicitPlane) {
			return explicitPlane && explicit.stream()
					.anyMatch(row -> row[0] == subjectId && row[1] == predicateId && row[2] == objectId
							&& row[3] == contextId);
		}

		@Override
		public void close() {
		}

		private long exactPredicateJoin(long leftPredicate, int leftComponent, long rightPredicate,
				int rightComponent) {
			Map<Long, Long> left = frequencies(leftPredicate, leftComponent);
			Map<Long, Long> right = frequencies(rightPredicate, rightComponent);
			long rows = 0L;
			for (Map.Entry<Long, Long> entry : left.entrySet()) {
				rows += entry.getValue() * right.getOrDefault(entry.getKey(), 0L);
			}
			return rows;
		}

		private Map<Long, Long> frequencies(long predicate, int component) {
			HashMap<Long, Long> frequencies = new HashMap<>();
			for (long[] row : explicit) {
				if (row[1] == predicate) {
					frequencies.merge(row[component], 1L, Long::sum);
				}
			}
			return frequencies;
		}
	}
}
